PAGE_HTML = r"""<!DOCTYPE html>
<html lang="zh"><head><meta charset="utf-8">
<title>工作流</title>
<style>
:root,html[data-wf="light"]{--bg:#f3f5f9;--panel:#ffffff;--line:#e5e7eb;--fg:#1f2937;--dim:#6b7280;--acc:#3b6fff;--ok:#22a45d;--bad:#e5484d;--card:#ffffff;--inp:#ffffff;--dotbg:#f3f5f9;--dot:rgba(127,140,160,.35)}
html[data-wf="dark"]{--bg:#16181d;--panel:#1c1f26;--line:#30363d;--fg:#e6edf3;--dim:#8b949e;--acc:#5a8bff;--ok:#2ea95c;--bad:#e5484d;--card:#22262e;--inp:#12151a;--dotbg:#16181d;--dot:rgba(127,140,160,.25)}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:13px/1.5 -apple-system,"PingFang SC",sans-serif;display:flex;height:100vh;overflow:hidden}
#side{width:230px;background:var(--panel);border-right:1px solid var(--line);display:flex;flex-direction:column}
#side h3{margin:0;padding:12px;font-size:14px;border-bottom:1px solid var(--line)}
#list{flex:1;overflow:auto}
.wf{padding:10px 12px;border-bottom:1px solid #f0f1f4;cursor:pointer}
.wf:hover{background:#f6f8fc}.wf.on{background:#eef3ff}
.wf b{display:block;font-weight:600}.wf small{color:var(--dim)}
.newbtn{margin:10px;padding:9px;background:var(--acc);color:#fff;border:0;border-radius:8px;cursor:pointer;width:calc(100% - 20px);font-size:13px}
#main{flex:1;display:flex;flex-direction:column;position:relative;min-width:0}
#bar{padding:8px 12px;background:var(--panel);border-bottom:1px solid var(--line);display:flex;gap:8px;align-items:center;flex-wrap:wrap}
#bar button{padding:6px 14px;border:1px solid var(--acc);background:var(--acc);color:#fff;border-radius:8px;cursor:pointer;font-size:13px}
#bar button.pri{background:var(--acc);border-color:var(--acc);color:#fff}
#bar button.run{background:#22a45d;border-color:#22a45d;color:#fff}
#bar button:disabled{opacity:.45;cursor:default}
#canvas{flex:1;position:relative;overflow:auto;background-image:radial-gradient(var(--dot) 1px,transparent 1px);background-size:24px 24px}
#nodes{position:absolute;inset:0}
#edges{position:absolute;inset:0;pointer-events:none}
.node{position:absolute;width:252px;background:var(--card);border:1px solid var(--line);border-radius:12px;box-shadow:0 2px 10px rgba(31,41,55,.08)}
.node.sel{border-color:var(--acc);box-shadow:0 0 0 3px rgba(59,111,255,.15)}
.node.tgt{border-color:var(--ok)!important;box-shadow:0 0 0 4px rgba(34,164,93,.22)!important}
.nhead{display:flex;align-items:center;gap:6px;padding:8px 10px 6px;cursor:grab;border-bottom:1px dashed #f0f1f4}
.nhead:active{cursor:grabbing}
.st-dot{width:9px;height:9px;border-radius:50%;background:#c3c9d4;flex:none}
.st-dot.running{background:var(--acc);animation:pulse 1s infinite}
.st-dot.done{background:var(--ok)}.st-dot.failed{background:var(--bad)}
.st-dot.awaiting{background:#b8860b}
@keyframes pulse{50%{opacity:.35}}
.st-txt{font-size:11px;color:var(--dim)}
.ndel{margin-left:auto;border:0;background:none;color:var(--dim);cursor:pointer;font-size:14px}
.ndel:hover{color:var(--bad)}
.nbody{padding:8px 10px 10px;display:flex;flex-direction:column;gap:7px}
.node input,.node select,.node textarea{width:100%;background:var(--inp);color:var(--fg);border:1px solid #d7dbe2;border-radius:8px;padding:6px 8px;font:12.5px/1.5 sans-serif}
.node textarea{min-height:64px;resize:vertical}
.nlabel{font-size:11px;color:var(--dim)}
.skchip{display:inline-block;background:#eef3ff;color:var(--acc);border-radius:6px;padding:2px 8px;margin:2px;font-size:11px}
.apt{display:flex;justify-content:center;align-items:center;height:52px;border:1px dashed #d7dbe2;border-radius:8px;color:var(--dim);font-size:11px}
.port{position:absolute;width:14px;height:14px;border-radius:50%;background:var(--acc);border:2px solid #fff;box-shadow:0 1px 4px rgba(31,41,55,.25);z-index:3;pointer-events:auto;cursor:crosshair;transition:transform .12s}
.port:hover{transform:scale(1.4)}
#edges path{transition:stroke-width .1s}
#edges path:hover{stroke-width:4.5}
#err{position:absolute;left:16px;right:16px;top:10px;background:#fdecec;color:var(--bad);border:1px solid #f5c2c2;padding:8px 12px;border-radius:8px;white-space:pre-wrap;display:none;z-index:9}
#out{position:absolute;right:0;top:0;width:380px;max-height:100%;background:var(--panel);border-left:1px solid var(--line);box-shadow:-4px 0 14px rgba(31,41,55,.08);overflow:auto;padding:12px;display:none;z-index:8}
#out pre{white-space:pre-wrap;font:12px/1.7 sans-serif;margin:8px 0 0}
#modal{position:fixed;inset:0;background:rgba(0,0,0,.4);display:none;align-items:center;justify-content:center;z-index:99}
#modal .box{background:var(--panel);color:var(--fg);border:1px solid var(--line);border-radius:12px;padding:16px;width:320px;box-shadow:8px 0 30px rgba(0,0,0,.25)}
#modal input{width:100%;background:var(--inp);color:var(--fg);border:1px solid var(--line);border-radius:8px;padding:8px 10px;font:13px sans-serif;margin:10px 0}
#modal .row{display:flex;gap:8px;justify-content:flex-end}
#modal button{padding:6px 14px;border-radius:8px;border:1px solid var(--line);background:var(--card);color:var(--fg);cursor:pointer}
#modal button.pri{background:var(--acc);border-color:var(--acc);color:#fff}
</style></head><body>
<div id="side"><h3>工作流</h3><button class="newbtn" onclick="createWF()">+ 新建工作流</button><div id="list"></div></div>
<div id="main"><div id="bar">
<button onclick="addNode()">+ 添加节点</button>
<button class="pri" onclick="saveWF()">保存</button>
<button class="run" id="runBtn" onclick="runWF()">▶ 运行</button>
<button id="stopBtn" onclick="stopRun()" disabled>■ 停止</button>
<span id="runStat"></span>
<button style="margin-left:auto" onclick="delWF()">删除</button>
</div><div id="canvas"><svg id="edges"></svg><div id="nodes"></div></div></div>
<div id="err"></div><div id="out"></div>
<div id="modal"><div class="box"><div id="modalTitle" style="font-weight:600"></div><input id="modalInput" style="display:none"><div class="row" style="margin-top:12px"><button id="modalNo">取消</button><button id="modalYes" class="pri">确定</button></div></div></div>
<script>
const CFG={base:(sessionStorage.getItem('eazybot_desktop_api_origin')||'').replace(/\/+$/,''),
tok:sessionStorage.getItem('eazybot_desktop_auth_token')||sessionStorage.getItem('eazybot_desktop_preview_token')||localStorage.getItem('eazybot_auth_token')||''};
const API=CFG.base+'/api/workflow-plus';
const $=id=>document.getElementById(id);
const esc=s=>String(s||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
async function j(url,opt){const h={'Content-Type':'application/json'};if(CFG.tok)h.Authorization='Bearer '+CFG.tok;
const r=await fetch(url,{headers:h,...opt});let d={};try{d=await r.json()}catch(e){}
if(!r.ok){throw (d.detail||d.errors||d)}return d}
let WFS=[],WF=null,RUN=null,POLLID=null,AGS=[],CONNECT=null,DRAG=null,TEMP=null;
function banner(msg,ms){const e=$('err');e.style.display='block';e.textContent=msg;setTimeout(()=>{e.style.display='none'},ms||4000)}
async function loadList(){try{WFS=(await j(API+'/workflows')).workflows}catch(e){WFS=[]}
$('list').innerHTML=WFS.map(w=>'<div class="wf '+(WF&&WF.id===w.id?'on':'')+'" onclick="openWF(\''+w.id+'\')"><b>'+esc(w.name)+'</b><small>'+w.node_count+' 节点 / '+w.edge_count+' 边</small></div>').join('')||'<div style="padding:12px;color:var(--dim)">还没有工作流</div>'}
async function createWF(){showModal('未命名工作流',async name=>{
try{const d=await j(API+'/workflows',{method:'POST',body:JSON.stringify({name:name})});WF=d;await loadList();openWF(d.id)}
catch(e){banner('创建失败: '+JSON.stringify(e),6000)}})}
async function openWF(id){WF=await j(API+'/workflows/'+id);RUN=null;stopPoll();document.querySelectorAll('.wf').forEach(e=>e.classList.toggle('on',e.dataset.id===id));hideOut();render()}
function nodeStatus(nid){return RUN&&RUN.nodes&&RUN.nodes[nid]?(RUN.nodes[nid].status||''):''}
function render(){$('nodes').innerHTML=(WF&&WF.nodes||[]).map(nodeHTML).join('');bindHeads();bindPorts();drawEdges();updateStat()}
function nodeHTML(n){const st=nodeStatus(n.id);
const stMap={running:['running','运行中'],done:['done','完成'],failed:['failed','失败'],awaiting:['awaiting','等待审批'],pending:['','排队中']};
const cls=stMap[st]?stMap[st][0]:'',txt=stMap[st]?stMap[st][1]:'空闲';
const ags=(AGS.length?AGS:[{id:'',name:'(默认智能体)'}]);
return '<div class="node" id="nd-'+n.id+'" data-id="'+n.id+'" style="left:'+(n.x||60)+'px;top:'+(n.y||60)+'px">'
+'<div class="nhead"><span class="st-dot '+cls+'"></span><span class="st-txt">'+txt+'</span><span class="ndel" onclick="delNode(\''+n.id+'\')">✕</span></div>'
+'<div class="nbody">'
+'<input value="'+esc(n.title)+'" placeholder="节点标题" oninput="setNode(\''+n.id+'\',\'title\',this.value)">'
+'<select onchange="setNode(\''+n.id+'\',\'agent\',this.value)">'+ags.map(a=>'<option '+(a.id===(n.agent||'')?'selected':'')+' value="'+esc(a.id)+'">'+esc(a.name)+'</option>').join('')+'</select>'
+'<div class="nlabel">汇聚策略</div>'
+'<select onchange="setNode(\''+n.id+'\',\'join\',this.value)"><option value="all" '+((n.join||'all')==='all'?'selected':'')+'>全部入口(等所有上游完成)</option><option value="any" '+(n.join==='any'?'selected':'')+'>任一入口(首个上游完成即开始)</option></select>'
+'<div class="nlabel"><input type="checkbox" style="width:auto;margin:0 4px 0 0" '+(n.approval?'checked':'')+' onchange="setNode(\''+n.id+'\',\'approval\',this.checked)">完成后审批</div>'
+'<div>'+(n.skills||[]).map((sk,i)=>'<span class="skchip">'+esc(sk)+'<span style="cursor:pointer;margin-left:4px" onclick="delSkill(\''+n.id+'\','+i+')">×</span></span>').join('')+'</div>'
+'<select onchange="if(this.value){addSkill(\''+n.id+'\',this.value);this.selectedIndex=0}"><option value="">+ 选择技能</option>'+(SKILLS.filter(s=>!(n.skills||[]).includes(s.name)).map(s=>'<option value="'+esc(s.name)+'">'+esc(s.name)+'</option>').join('')||'<option value="" disabled>暂无可用技能</option>')+'</select>'
+'<textarea placeholder="描述这个 Agent 要做什么..." oninput="setNode(\''+n.id+'\',\'input\',this.value)">'+esc(n.input||'')+'</textarea>'
+'<div class="apt">附件:暂未开放</div>'
+'</div>'
+'<div class="port in" data-id="'+n.id+'" data-port="in" style="left:-8px;top:30px"></div>'
+'<div class="port out" data-id="'+n.id+'" data-port="out" style="right:-8px;top:30px"></div>'
+'<div class="port out" data-id="'+n.id+'" data-port="out2" style="right:-8px;bottom:16px"></div>'
+'</div>'}
function setNode(id,k,v){const n=WF&&WF.nodes.find(x=>x.id===id);if(n)n[k]=v}
function addSkill(id,s){const n=WF.nodes.find(x=>x.id===id);if(!n)return;n.skills=n.skills||[];if(!n.skills.includes(s))n.skills.push(s);render()}
function delSkill(id,i){const n=WF.nodes.find(x=>x.id===id);n.skills.splice(i,1);render()}
function delNode(id){WF.nodes=WF.nodes.filter(n=>n.id!==id);WF.edges=WF.edges.filter(e=>e.source!==id&&e.target!==id);render()}
function addNode(){WF.nodes.push({id:'n'+Date.now().toString(36),title:'节点 '+(WF.nodes.length+1),agent:'',join:'all',approval:false,skills:[],input:'',x:60+WF.nodes.length*46,y:60+WF.nodes.length*34});render()}
function delWF(){if(!WF||!WF.id)return;showConfirm('删除该工作流?',ok=>{if(!ok)return;
j(API+'/workflows/batch-delete',{method:'POST',body:JSON.stringify({ids:[WF.id]})}).then(()=>{WF=null;loadList();$('nodes').innerHTML='';drawEdges()})})}
function pxy(id,port){const el=$('nd-'+id);if(!el)return null;
return {x:el.offsetLeft+(port==='in'?-8:252),y:el.offsetTop+(port==='out2'?el.offsetHeight-22:30)}}
function tname(id){const n=WF&&WF.nodes.find(x=>x.id===id);return n?esc(n.title||id):id}
function cvpt(e){const c=$('canvas'),rc=c.getBoundingClientRect();return{x:e.clientX-rc.left+c.scrollLeft,y:e.clientY-rc.top+c.scrollTop}}
function ndAt(x,y){const el=document.elementFromPoint(x,y);const nd=el?el.closest('.node'):null;return(nd&&nd.parentNode===$('nodes'))?nd.dataset.id:null}
const ROUTES={success:['#3b6fff','正常返回','上游节点成功完成后才触发本节点'],failure:['#e5484d','执行失败','上游节点执行失败时才触发本节点(错误处理分支)'],always:['#b8860b','任一结果','无论上游成功或失败都触发本节点']};
function cycleRoute(i){const e=WF.edges[i];if(!e)return;const order=['success','failure','always'];e.route=order[(order.indexOf(e.route||'success')+1)%3];drawEdges();
banner('连线条件: '+tname(e.source)+' → '+tname(e.target)+' = 上游'+(ROUTES[e.route||'success'][1]),2600)}
function drawEdges(){const svg=$('edges'),cv=$('canvas');svg.setAttribute('width',Math.max(cv.scrollWidth,3000));svg.setAttribute('height',Math.max(cv.scrollHeight,2200));
let html='<defs>';
Object.keys(ROUTES).forEach(k=>{html+='<marker id="ar-'+k+'" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0,0 L10,5 L0,10 z" fill="'+ROUTES[k][0]+'"/></marker>'});
html+='</defs>';
(WF&&WF.edges||[]).forEach((e,i)=>{const a=pxy(e.source,'out'),b=pxy(e.target,'in');if(!a||!b)return;const dx=Math.max(50,(b.x-a.x)/2);
const rk=e.route||'success',rc=ROUTES[rk][0],rn=ROUTES[rk][1];
const mx=(a.x+b.x)/2,my=(a.y+b.y)/2;
html+='<path d="M'+a.x+','+a.y+' C'+(a.x+dx)+','+a.y+' '+(b.x-dx)+','+b.y+' '+b.x+','+b.y+'" stroke="'+rc+'" stroke-width="2.5" fill="none" marker-end="url(#ar-'+rk+')" style="pointer-events:stroke;cursor:pointer" data-i="'+i+'" ondblclick="cycleRoute('+i+')">'
+'<title>'+tname(e.source)+' → '+tname(e.target)+'\n连线含义: 上游'+rn+'\n双击切换条件(正常/失败/任一),点中间圆点×删除连线\n箭头指向下游</title></path>'
+'<circle cx="'+mx+'" cy="'+my+'" r="9" fill="#fff" stroke="'+rc+'" stroke-width="1.5" style="pointer-events:all;cursor:pointer" onclick="delEdge('+i+')"><title>删除连线 '+tname(e.source)+' → '+tname(e.target)+'</title></circle>'
+'<text x="'+mx+'" y="'+(my+3)+'" text-anchor="middle" fill="'+rc+'" font-size="9" style="pointer-events:none">×</text>'
+'<text x="'+mx+'" y="'+(my-15)+'" text-anchor="middle" fill="'+rc+'" font-size="10.5" style="pointer-events:none;paint-order:stroke" stroke="var(--panel)" stroke-width="3" font-weight="600">上游'+rn+'</text>'});
if(TEMP){html+='<path d="M'+TEMP.x1+','+TEMP.y1+' C'+(TEMP.x1+60)+','+TEMP.y1+' '+(TEMP.x2-60)+','+TEMP.y2+' '+TEMP.x2+','+TEMP.y2+'" stroke="#3b6fff" stroke-width="2" stroke-dasharray="6 4" fill="none"/>'}
svg.innerHTML=html}
function delEdge(i){WF.edges.splice(i,1);drawEdges()}
function updateStat(){$('runStat').textContent=RUN?('运行: '+RUN.status+(RUN.error?(' · '+RUN.error):'')):'';
$('runBtn').disabled=!!(RUN&&RUN.status==='running');$('stopBtn').disabled=!(RUN&&RUN.status==='running')}
function bindHeads(){document.querySelectorAll('.node .nhead').forEach(h=>{h.onmousedown=ev=>{if(ev.target.classList.contains('ndel'))return;
const el=h.closest('.node');DRAG={id:el.dataset.id,dx:ev.clientX-el.offsetLeft,dy:ev.clientY-el.offsetTop}}})}
function bindPorts(){document.querySelectorAll('.port').forEach(p=>{if(p.dataset.port==='in')return;
p.onmousedown=ev=>{ev.preventDefault();ev.stopPropagation();CONNECT={from:p.dataset.id,port:p.dataset.port};document.body.style.cursor='crosshair'}})}
document.addEventListener('mousemove',e=>{
if(CONNECT){const a=pxy(CONNECT.from,'out');const pt=cvpt(e);TEMP={x1:a.x,y1:a.y,x2:pt.x,y2:pt.y};drawEdges();
const nid=ndAt(e.clientX,e.clientY);document.querySelectorAll('.node').forEach(el=>el.classList.toggle('tgt',!!nid&&el.dataset.id===nid&&nid!==CONNECT.from))}
if(DRAG){const el=$('nd-'+DRAG.id);if(el){el.style.left=(e.clientX-DRAG.dx)+'px';el.style.top=(e.clientY-DRAG.dy)+'px'}}});
document.addEventListener('mouseup',e=>{
if(CONNECT){document.body.style.cursor='';document.querySelectorAll('.node').forEach(el=>el.classList.remove('tgt'));
const nid=ndAt(e.clientX,e.clientY);if(nid&&nid!==CONNECT.from){const dup=WF.edges.some(x=>x.source===CONNECT.from&&x.target===nid);
if(dup){banner('这两个节点之间已有连线',2200)}else{WF.edges.push({id:CONNECT.from+'-'+nid,source:CONNECT.from,target:nid,route:'success'});
banner('已连线: '+tname(CONNECT.from)+' → '+tname(nid)+'（上游正常返回时触发本节点；双击连线可改为「失败/任一」条件）',4200);render()}}
CONNECT=null;TEMP=null;drawEdges()}
if(DRAG){const el=$('nd-'+DRAG.id);if(el){const n=WF.nodes.find(x=>x.id===DRAG.id);n.x=el.offsetLeft;n.y=el.offsetTop;drawEdges()}DRAG=null}});
function saveWF(){if(!WF)return;const nodes=WF.nodes,ids=nodes.map(n=>n.id),edges=WF.edges,errs=[];
if(!nodes.length)errs.push('至少需要一个节点');
nodes.forEach(n=>{if(!n.title||!n.title.trim())errs.push((n.title||n.id)+': 缺标题');
if(!n.input||!n.input.trim())errs.push((n.title||n.id)+': 缺任务描述')});
edges.forEach(e=>{if(!ids.includes(e.source)||!ids.includes(e.target))errs.push('边引用了不存在的节点');
if(e.source===e.target)errs.push('不允许自连')});
if(errs.length){$('err').style.display='block';$('err').textContent='无法保存:\n'+errs.join('\n');return}
j(API+'/workflows/'+WF.id,{method:'PATCH',body:JSON.stringify({name:WF.name,nodes:nodes.map(n=>({id:n.id,title:n.title,agent:n.agent,join:n.join||'all',approval:!!n.approval,skills:n.skills||[],input:n.input,x:n.x,y:n.y})),edges:WF.edges,viewport:WF.viewport||{x:0,y:0,zoom:1}})})
.then(d=>{WF=d;loadList();banner('已保存 ✓',1500)}).catch(er=>{$('err').style.display='block';$('err').textContent='保存被拒绝: '+JSON.stringify(er)})}
let POLLID=null;
function runWF(){if(!WF||!WF.id)return;j(API+'/workflows/'+WF.id+'/run',{method:'POST'}).then(d=>{RUN={run_id:d.run_id,status:'running',nodes:{}};updateStat();startPoll()}).catch(e=>banner('启动失败: '+JSON.stringify(e),4000))}
function stopRun(){if(!RUN||!RUN.run_id)return;j(API+'/workflows/'+WF.id+'/runs/'+RUN.run_id+'/stop',{method:'POST'}).then(()=>{banner('停止信号已发送',2000)}).catch(e=>banner(JSON.stringify(e),3000))}
function startPoll(){stopPoll();POLLID=setInterval(pollOnce,2000)}
function stopPoll(){if(POLLID){clearInterval(POLLID);POLLID=null}}
async function pollOnce(){if(!RUN||!RUN.run_id)return;
try{const d=await j(API+'/workflows/'+WF.id+'/runs/'+RUN.run_id);RUN=d;updateStat();
if(WF)render();if(RUN.status!=='running'){stopPoll()}}catch(e){}}
function showOut(nid){if(!WF)return;const n=WF.nodes.find(x=>x.id===nid);if(!n)return;
const rec=RUN&&RUN.nodes&&RUN.nodes[nid]?RUN.nodes[nid]:{};
$('out').style.display='block';
$('out').innerHTML='<b>'+esc(n.title||n.id)+'</b> <button onclick="hideOut()" style="float:right;background:none;border:0;color:var(--dim);cursor:pointer">✕关闭</button><pre>'+esc((rec&&(rec.output||rec.error))||'(未运行)')+'</pre>'}
function hideOut(){$('out').style.display='none'}
document.addEventListener('click',e=>{if(!RUN)return;const nd=e.target.closest?e.target.closest('.node'):null;
if(nd&&WF&&!e.target.closest('input,select,textarea,button,.port,svg'))showOut(nd.dataset.id)});
let AGS=[];
let SKILLS=[];
async function loadSkills(){try{SKILLS=await j((CFG.base||'')+'/api/skills')}catch(e){SKILLS=[]}}
async function init(){try{AGS=(await j(API+'/agents')).agents||[]}catch(e){AGS=[]}await loadSkills();await loadList();render()}
init();
</script></body></html>"""